    var a = c.inHouse;
    if (!isNum(a.salary) || a.salary <= 0) throw inputError('"compare.inHouse.salary" must be greater than 0.');
    var load = n0(a.loadPct) / 100, rec = n0(a.recruitPct) / 100;
