  var weakLinks = weak.map(function (r) { var d = byId[r.id]; return { id: r.id, name: r.name, score: r.score, inStageFocus: focus.indexOf(r.id) > -1, read: d.weak, move: d.move, skills: d.skills, evidence: d.evidence }; });
